export type ParsedCompleteOrderInstruction<
  TProgram extends string = typeof FARMER_CORE_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    config: TAccountMetas[0];
    order: TAccountMetas[1];
    warehouse: TAccountMetas[2];
    mint: TAccountMetas[3];
    /** Must already exist; the program does not create payout accounts. */
    farmerTokenAccount: TAccountMetas[4];
    logisticsTokenAccount: TAccountMetas[5];
    escrow: TAccountMetas[6];
    /** Escrow rent goes back to the customer, who paid it at `create_order`. */
    customer: TAccountMetas[7];
    operator: TAccountMetas[8];
    tokenProgram: TAccountMetas[9];
  };
  data: CompleteOrderInstructionData;
};

export function parseCompleteOrderInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedCompleteOrderInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 10) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 10,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      config: getNextAccount(),
      order: getNextAccount(),
      warehouse: getNextAccount(),
      mint: getNextAccount(),
      farmerTokenAccount: getNextAccount(),
      logisticsTokenAccount: getNextAccount(),
      escrow: getNextAccount(),
      customer: getNextAccount(),
      operator: getNextAccount(),
      tokenProgram: getNextAccount(),
    },
    data: getCompleteOrderInstructionDataDecoder().decode(instruction.data),
  };
}
